function clubLogo(club, size = 20) {
  const customUrl = CUSTOM_CLUB_LOGOS[club];
  if (customUrl) {
    return `<img class="club-logo-img" src="${customUrl}" alt="${club}" style="width:${size}px;height:${size}px">`;
  }
  const cr = CLUB_CRESTS[club] || { c1: "#166534", c2: "#0b2919", acc: "#22c55e", code: (club || "FC").slice(0, 3).toUpperCase(), pat: "shield" };
  const textColor = (cr.c1 === "#FFFFFF" || cr.c1 === "#FDE100" || cr.c1 === "#FFCD00") ? "#111827" : "#FFFFFF";
  if (cr.pat === "circle") {
    return `<svg class="club-svg" width="${size}" height="${size}" viewBox="0 0 32 32" aria-hidden="true">
      <circle cx="16" cy="16" r="15" fill="${cr.c1}" stroke="${cr.acc}" stroke-width="2"/>
      <circle cx="16" cy="16" r="10.5" fill="${cr.c2}" opacity="0.28"/>
      <text x="16" y="19.5" text-anchor="middle" fill="${textColor}" font-family="Outfit, sans-serif" font-weight="800" font-size="9.5">${cr.code}</text>
    </svg>`;
  }
  if (cr.pat === "stripes") {
    return `<svg class="club-svg" width="${size}" height="${size}" viewBox="0 0 32 32" aria-hidden="true">
      <path d="M5,4 H27 V17 C27,24 16,29 16,29 C16,29 5,24 5,17 Z" fill="${cr.c1}" stroke="${cr.acc}" stroke-width="2"/>
      <path d="M11,5 V25 M16,5 V27 M21,5 V25" stroke="${cr.c2}" stroke-width="3.2"/>
      <rect x="5" y="11" width="22" height="9" fill="rgba(0,0,0,0.65)"/>
      <text x="16" y="18.2" text-anchor="middle" fill="#FFFFFF" font-family="Outfit, sans-serif" font-weight="800" font-size="9">${cr.code}</text>
    </svg>`;
  }
  return `<svg class="club-svg" width="${size}" height="${size}" viewBox="0 0 32 32" aria-hidden="true">
    <path d="M5,4 H27 V17 C27,24 16,29 16,29 C16,29 5,24 5,17 Z" fill="${cr.c1}" stroke="${cr.acc}" stroke-width="2"/>
    <path d="M16,5 H26 V17 C26,22.5 16,27.5 16,27.5 Z" fill="${cr.c2}" opacity="0.32"/>
    <text x="16" y="19.2" text-anchor="middle" fill="${textColor}" font-family="Outfit, sans-serif" font-weight="800" font-size="9.2">${cr.code}</text>
  </svg>`;
}

