function normPos(raw) {
  if (!raw) return null;
  const k = String(raw).trim().toLocaleUpperCase("tr-TR");
  if (!k) return null;
  return ALIASES[k] || ALIASES[k.replace(/İ/g, "I")] || null;
}

// Bütçe Draftında oyuncuların fiyatlarından reytinglerinin tahmin edilmesini önleyen deterministik ±5-9 M€ piyasa dalgalanması
function calcBasePriceWithVariance(name, rating, idx) {
  const r = rating || 75;
  let base;
  if (r <= 72) base = 6;
  else if (r <= 75) base = 8 + (r - 72);
  else if (r <= 79) base = 11 + Math.round((r - 75) * 1.5);
  else if (r <= 83) base = 17 + Math.round((r - 79) * 2.2);
  else if (r <= 87) base = 26 + Math.round((r - 83) * 3.5);
  else base = 40 + Math.round((r - 87) * 4.8);

  // Oyuncu ismine göre sabit ama tahmin edilemez ±6 M€ sapma (Örn. 84'lük bir oyuncu 21 M€ da olabilir 32 M€ da)
  let hash = idx * 31;
  for (let i = 0; i < name.length; i++) {
    hash = ((hash << 5) - hash) + name.charCodeAt(i);
    hash |= 0;
  }
  const swing = (Math.abs(hash) % 13) - 6; // -6 ile +6 M€ arası sapma
  return Math.max(4, base + swing);
}

let P = [], CLUBS = [], LEAGUES = [];
function setPool(rows) {
  P = rows.map((x, i) => {
    const r = x.rating;
    return {
      id: i,
      n: x.name,
      c: x.club,
      lg: x.league || CLUB_TO_LEAGUE[x.club] || "Diğer Takımlar",
      r,
      pos: x.position || "MID",
      price: x.price != null ? x.price : calcBasePriceWithVariance(x.name, r, i)
    };
  });
  CLUBS = [...new Set(P.map(p => p.c))];
  LEAGUES = [...new Set(P.map(p => p.lg))];
}

const DEFAULT_ROWS = Object.entries(DATA).flatMap(([c, l]) =>
  l.map(([n, r], i) => ({
    name: n,
    club: c,
    league: CLUB_TO_LEAGUE[c] || "Premier Lig",
    rating: r,
    position: ({ G: "GK", D: "DEF", M: "MID", F: "FWD" })[(PS[c] || "")[i]] || "MID"
  }))
);
setPool(DEFAULT_ROWS);

const HD = {
  name: ["name", "oyuncu", "isim", "ad"],
  club: ["club", "kulup", "kulüp", "takim", "takım"],
  league: ["league", "lig"],
  rating: ["rating", "reyting", "puan"],
  position: ["position", "pozisyon", "mevki"]
};

function parseRating(v, w, who) {
  const t = String(v == null ? "" : v).trim();
  if (!t) return null;
  const n = +t;
  if (Number.isInteger(n) && n >= 1 && n <= 99) return n;
  w.push(who + ": reyting 1–99 olmalı (" + t + ")");
  return null;
}

function parseList(txt) {
  const w = [], rows = [];
  const lines = txt.replace(/^\uFEFF/, "").split(/\r?\n/).map(l => l.trim());
  const first = lines.find(Boolean) || "";
  const d = [";", "\t", ","].find(x => first.includes(x));
  if (d) {
    const hd = first.split(d).map(x => x.trim().toLocaleLowerCase("tr-TR"));
    const ix = {};
    for (const k in HD) ix[k] = hd.findIndex(x => HD[k].includes(x));
    if (ix.name >= 0) {
      for (const l of lines.slice(lines.indexOf(first) + 1)) {
        if (!l) continue;
        const c = l.split(d).map(x => x.trim());
        const name = c[ix.name];
        if (!name) continue;
        const clubName = (ix.club >= 0 && c[ix.club]) || "Kulüpsüz";
        rows.push({
          name,
          club: clubName,
          league: (ix.league >= 0 && c[ix.league]) || CLUB_TO_LEAGUE[clubName] || "Diğer Takımlar",
          rating: parseRating(ix.rating >= 0 ? c[ix.rating] : "", w, name),
          position: ix.position >= 0 ? normPos(c[ix.position]) : null
        });
      }
      return { format: "csv", rows, warnings: w };
    }
  }
  let club = "Kulüpsüz";
  let currentLeague = "Diğer Takımlar";
  const knownLeagues = ["premier lig", "la liga", "serie a", "bundesliga", "ligue 1", "liga portugal", "eredivise", "eredivisie", "trendyol süper lig", "diğer takımlar"];
  for (const l of lines) {
    if (!l || /kadro(lar)? reytingleri/i.test(l) || /5 büyük lig dışı/i.test(l)) continue;
    const low = l.toLocaleLowerCase("tr-TR");
    if (knownLeagues.includes(low)) {
      if (low === "eredivise") currentLeague = "Eredivisie";
      else currentLeague = LEAGUES_META.find(m => m.id.toLocaleLowerCase("tr-TR") === low)?.id || l;
      continue;
    }
    const m = l.match(/^(.*?)\s+(\d{1,3})(?:\s+(\S+(?:\s\S+)?))?$/);
    if (!m) {
      club = l;
      if (CLUB_TO_LEAGUE[club]) currentLeague = CLUB_TO_LEAGUE[club];
      continue;
    }
    const pos = m[3] ? normPos(m[3]) : null;
    if (m[3] && !pos) w.push(m[1] + ": pozisyon tanınmadı (" + m[3] + ")");
    rows.push({
      name: m[1].trim(),
      club,
      league: CLUB_TO_LEAGUE[club] || currentLeague,
      rating: parseRating(m[2], w, m[1]),
      position: pos || "MID"
    });
  }
  return { format: "text", rows, warnings: w };
}
